    def add_member(person, is_founder):
        member = TeamMember(name=person["name"], is_founder=is_founder)
        extension = person["picture"].split(".")[-1]
        member.image.save(
            slugify(person["name"]) + f".{extension}",
            open("mixity/static/" + person["picture"], "rb"),
        )
        for lang in ["fr", "en", "es"]:
            translation.activate(lang)
            setattr(member, f"pronouns_{lang}", str(person["pronouns"]))
            setattr(member, f"job_{lang}", str(person.get("status", "")))
            setattr(member, f"description_{lang}", str(person["summary"]))
        member.save()

    for founder in founders:
        add_member(founder, True)
    for team_member in team:
        add_member(team_member, False)


